# Filter rows to find the Fantasia Festival date
fantasia_row = df[df['Festival'] == 'Fantasia Festival']
if not fantasia_row.empty:
    fantasia_date = fantasia_row['Date'].iloc[0]
    # Extract the first date part (assuming format like "Jul 18, Jul 25")
    fantasia_first_date_str = fantasia_date.split(',')[0].strip()
    # Convert to datetime for comparison (assuming year 2011 from context)
    import datetime
    try:
        fantasia_first_date = datetime.datetime.strptime(fantasia_first_date_str + " 2011", "%b %d %Y")
    except ValueError:
        # Handle date ranges like "Feb 2–5"
        if '–' in fantasia_first_date_str:
            start_part = fantasia_first_date_str.split('–')[0].strip()
            fantasia_first_date = datetime.datetime.strptime(start_part + " 2011", "%b %d %Y")
        else:
            fantasia_first_date = None
else:
    fantasia_first_date = None

# If we have a valid Fantasia date, find festivals with earlier dates
if fantasia_first_date:
    earlier_festivals = []
    for idx, row in df.iterrows():
        festival_date_str = row['Date']
        # Extract first date part
        first_date_part = festival_date_str.split(',')[0].strip()
        try:
            festival_first_date = datetime.datetime.strptime(first_date_part + " 2011", "%b %d %Y")
        except ValueError:
            if '–' in first_date_part:
                start_part = first_date_part.split('–')[0].strip()
                festival_first_date = datetime.datetime.strptime(start_part + " 2011", "%b %d %Y")
            else:
                festival_first_date = None
        if festival_first_date and festival_first_date < fantasia_first_date:
            earlier_festivals.append((festival_first_date, row['Festival']))

    # Sort by date descending to get the one immediately before Fantasia
    if earlier_festivals:
        earlier_festivals.sort(key=lambda x: x[0], reverse=True)
        answer = earlier_festivals[0][1]
    else:
        answer = None
else:
    answer = None
